// ─── File: IocDemo.java ───
// The main method plays the role Spring's ApplicationContext normally plays:
// it constructs beans and injects their dependencies (manual IoC).
package com.bank.transfer;

import java.math.BigDecimal;
import java.util.logging.*;

public class IocDemo {
    private static final Logger log = Logger.getLogger(IocDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // ---- This block IS the Inversion of Control container (done by hand) ----
        AccountRepository repo = new InMemoryAccountRepository();
        AuditService audit = new AuditService();
        TransferService service = new TransferService(repo, audit); // constructor injection

        repo.save(new Account("SAV2001", "Rajesh", new BigDecimal("1000000")));
        repo.save(new Account("CUR3001", "Priya", new BigDecimal("250000")));

        log.info("=== Transfer via constructor-injected dependencies ===");
        service.transfer("SAV2001", "CUR3001", new BigDecimal("50000"));
    }
}

// ─── Would be in model/Account.java ───
class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;
    Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId; this.holderName = holderName; this.balance = balance;
    }
    String getAccountId() { return accountId; }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
    void debit(BigDecimal amt) { balance = balance.subtract(amt); }
    void credit(BigDecimal amt) { balance = balance.add(amt); }
}

// ─── Would be in repository/AccountRepository.java ───
interface AccountRepository {
    void save(Account a);
    Account findById(String id);
}

// ─── Would be in repository/InMemoryAccountRepository.java ───
class InMemoryAccountRepository implements AccountRepository {
    private final java.util.Map<String, Account> store = new java.util.HashMap<>();
    public void save(Account a) { store.put(a.getAccountId(), a); }
    public Account findById(String id) { return store.get(id); }
}

// ─── Would be in service/AuditService.java ───
class AuditService {
    private static final Logger log = Logger.getLogger(AuditService.class.getName());
    void record(String from, String to, BigDecimal amount) {
        log.info(() -> "AUDIT: transfer " + from + " -> " + to + " Rs." + amount);
    }
}

// ─── Would be in service/TransferService.java ───
// Dependencies are INJECTED through the constructor and stored in final fields.
class TransferService {
    private static final Logger log = Logger.getLogger(TransferService.class.getName());
    private final AccountRepository repo;   // final = immutable, always set
    private final AuditService audit;

    TransferService(AccountRepository repo, AuditService audit) {
        this.repo = repo;
        this.audit = audit;
    }

    void transfer(String fromId, String toId, BigDecimal amount) {
        Account from = repo.findById(fromId);
        Account to = repo.findById(toId);
        if (from.getBalance().compareTo(amount) < 0) {
            log.severe(() -> "Transfer failed: insufficient balance in " + fromId);
            return;
        }
        from.debit(amount);
        to.credit(amount);
        repo.save(from);
        repo.save(to);
        audit.record(fromId, toId, amount);
        log.info(() -> "Transfer OK. " + fromId + " balance Rs." + from.getBalance()
                + ", " + toId + " balance Rs." + to.getBalance());
    }
}

